'use client';

import { cn } from '@shared/lib/utils';
import type { HealthStatus } from '../types';
import {
  HEALTH_LABELS,
  HEALTH_BADGE_CLASSES,
  HEALTH_BADGE_SOLID_CLASSES,
  HEALTH_DOT_CLASSES,
  HEALTH_DOT_SOLID_CLASSES,
} from '../constants';

interface HealthBadgeProps {
  status: HealthStatus;
  size?: 'sm' | 'md';
  showLabel?: boolean;
  variant?: 'subtle' | 'solid';
  className?: string;
}

export function HealthBadge({
  status,
  size = 'sm',
  showLabel = true,
  variant = 'subtle',
  className,
}: HealthBadgeProps) {
  const badgeClass = variant === 'solid' ? HEALTH_BADGE_SOLID_CLASSES[status] : HEALTH_BADGE_CLASSES[status];
  const dotClass = variant === 'solid' ? HEALTH_DOT_SOLID_CLASSES[status] : HEALTH_DOT_CLASSES[status];

  return (
    <span
      data-testid={`health-badge-${status}`}
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full border font-semibold',
        size === 'sm' ? 'text-[10px] px-2 py-0.5' : 'text-xs px-2.5 py-1',
        badgeClass,
        className
      )}
    >
      <span className={cn('rounded-full', size === 'sm' ? 'w-1.5 h-1.5' : 'w-2 h-2', dotClass)} />
      {showLabel && <span className="uppercase tracking-wider">{HEALTH_LABELS[status]}</span>}
    </span>
  );
}
